'use strict';
const {strings,order,note,target,landmark} = FretLesson;
const app=document.querySelector('#app');
const leaveDialog=document.querySelector('#leave-dialog');
let state;
function reset(){state={view:'path',step:0,hint:0,solved:false,found:[],wrong:null,mistakes:0,hintsUsed:0};render();}
function mascot(){return `<svg class="mascot" viewBox="0 0 150 150" aria-hidden="true"><path d="M22 28Q75 6 128 28Q146 50 119 94L88 134Q75 149 62 134L31 94Q4 50 22 28" fill="#ffe39c" stroke="#e6bb63" stroke-width="3"/><path d="M30 32Q78 16 120 32" fill="none" stroke="#fff1c8" stroke-width="7" stroke-linecap="round"/><ellipse cx="57" cy="64" rx="5" ry="7" fill="#302345"/><ellipse cx="94" cy="64" rx="5" ry="7" fill="#302345"/><path d="M62 84Q76 97 90 84" fill="none" stroke="#302345" stroke-width="4" stroke-linecap="round"/><ellipse cx="43" cy="80" rx="9" ry="5" fill="#efac85"/><ellipse cx="108" cy="80" rx="9" ry="5" fill="#efac85"/><path d="m5 17 4-10 4 10 10 4-10 4-4 10-4-10-10-4M135 110l3-7 3 7 7 3-7 3-3 7-3-7-7-3" fill="#aa8be9"/></svg>`;}
function path(){return `<div class="shell"><aside class="sidebar"><div class="nav-item"><span class="nav-symbol" aria-hidden="true">⌁</span>Your trail</div><div class="sidebar-copy"><strong>Small steps. Big connections.</strong>Get to know the neck, one little discovery at a time.</div><div class="side-card"><span class="mini" aria-hidden="true">✳</span><strong>Guitar optional.</strong><p>Your curiosity is all you need. Jump in, tap around, and learn something new.</p></div></aside><main class="main-path"><div class="path-intro"><div><span class="eyebrow">YOUR DAILY GUITAR DETOUR</span><h1>A little less guessing.<br>A lot more guitar.</h1><p>Your fretboard adventure starts here.</p></div>${mascot()}</div><section class="unit-banner"><div><span class="eyebrow">UNIT 01 · MEET THE FRETBOARD</span><h2>Every note has a home.</h2></div><span class="unit-count">1 playable lesson</span></section><div class="trail"><section class="trail-stop"><button class="lesson-orb" data-action="start" aria-label="Start Find your C lesson">C</button><div class="stop-copy"><span class="eyebrow">START HERE</span><h3>Find your C</h3><p>One note. Six strings. A whole new view.</p><p class="lesson-summary">~3–5 min · Visual puzzles · Hints included</p><button class="primary" data-action="start">Let's play <span aria-hidden="true">→</span></button></div></section><section class="trail-stop"><div class="lesson-orb locked" aria-hidden="true">♧</div><div class="stop-copy locked-copy"><h3>Connect the dots</h3><p>Intervals · Coming later</p></div></section><section class="trail-stop"><div class="lesson-orb locked" aria-hidden="true">♧</div><div class="stop-copy locked-copy"><h3>Three's a chord</h3><p>Triads · Coming later</p></div></section></div><p class="footnote">A small prototype with one real lesson. No account. No audio. Just play.</p></main></div>`;}
function activeRow(row){return state.step===6||order[state.step]===row;}
function isFound(row){return state.step===6?state.found.includes(row):state.solved&&row===order[state.step];}
function board(){let html='<div class="board" role="group" aria-label="Guitar fretboard, high E at the top and low E at the bottom"><div class="fret-number">OPEN</div>';for(let f=1;f<=12;f++)html+=`<div class="fret-number ${[3,5,7,9,12].includes(f)?'marker':''}">${f}${[3,5,7,9,12].includes(f)?' ·':''}</div>`;strings.forEach((s,row)=>{const active=activeRow(row), showHints=state.step<6&&active;const near=landmark(row);const c=target(row);const openAdjacent=showHints&&state.hint>=2&&c===1;html+=`<div class="string-label ${active?'active':''} ${openAdjacent?'nut-note':''}" aria-label="${s.name}, open note ${s.open}">${s.open}<small>${row===0?'HIGH':row===5?'LOW':''}</small></div>`;for(let f=1;f<=12;f++){let label='',cls='';if(showHints&&state.hint>=1&&f===near){label=note(row,f);cls='landmark';}if(showHints&&state.hint>=2&&Math.abs(f-c)===1){label=note(row,f);cls='adjacent';}if(showHints&&state.hint>=3&&f===c){label='C';cls='revealed';}if(isFound(row)&&f===c){label='C';cls='found';}if(state.wrong===`${row}:${f}`){label='×';cls='miss';}const disabled=!active||state.solved||(state.step===6&&state.found.includes(row));html+=`<button class="fret ${active?'active':''} ${cls}" style="--wire:${1+(row*.3)}px" data-row="${row}" data-fret="${f}" ${disabled?'disabled':''} aria-label="${s.name} string, fret ${f}${label&&label!=='×'?`, ${label}`:''}${cls==='found'?', found':''}"><span class="dot" aria-hidden="true">${label}</span></button>`;}});return html+'</div>';}
function feedback(){if(state.solved)return `<div class="feedback success"><span class="feedback-icon" aria-hidden="true">✓</span><div><strong>${state.step===6?'All six. Nicely connected!':'That’s C. You found its home!'}</strong><p>${state.step===6?'You located C on every string. Your first trip around the neck is complete.':`${strings[order[state.step]].name} string · fret ${target(order[state.step])}. ${state.hint===3?'Followed the reveal? You’ll see this string again in the final round.':'Keep that spot in mind for the final round.'}`}</p></div></div>`;
if(state.step===6)return `<div class="feedback ${state.wrong?'help':''}"><span class="feedback-icon" aria-hidden="true">${state.wrong?'↻':'✦'}</span><div><strong>${state.wrong?'Keep exploring. That one isn’t C.':'Bring it all together.'}</strong><p>${state.found.length} of 6 found. Tap one C on each string. Correct notes stay green.</p></div></div>`;
const row=order[state.step],s=strings[row],f=landmark(row),c=target(row);
if(state.hint===1)return `<div class="feedback help"><span class="feedback-icon" aria-hidden="true">?</span><div><strong>A little landmark to help.</strong><p>${note(row,f)} is at fret ${f}, the closest of frets 3, 5, and 7 to C.${f===c?' This landmark is C itself. Tap it to continue.':' Each fret moves one half step. Can you work your way to C?'}</p></div></div>`;
if(state.hint===2)return `<div class="feedback help"><span class="feedback-icon" aria-hidden="true">↔</span><div><strong>C lives between B and C♯.</strong><p>${c===1?'The open B is just before C. C♯ is at fret 2.':`B is at fret ${c-1}. C♯ is at fret ${c+1}.`} Tap the spot between them.</p></div></div>`;
if(state.hint===3)return `<div class="feedback help"><span class="feedback-icon" aria-hidden="true">C</span><div><strong>Here’s C. Give it a tap.</strong><p>On the ${s.name} string, C is at fret ${c}. The purple circle shows you where.</p></div></div>`;
return `<div class="feedback"><span class="feedback-icon" aria-hidden="true">✦</span><div><strong>Start with the open ${s.open}.</strong><p>Each fret is one half step: A → A♯ → B → C → C♯ → D → D♯ → E → F → F♯ → G → G♯ → A. B–C and E–F have no sharp between them.</p></div></div>`;}
function lesson(){const final=state.step===6,row=order[state.step],s=strings[row];return `<main class="lesson-shell"><div class="lesson-progress"><button class="icon-button" data-action="exit" aria-label="Back to path">×</button><div class="track" role="progressbar" aria-label="Lesson progress" aria-valuemin="0" aria-valuemax="7" aria-valuenow="${state.step+(state.solved?1:0)}"><div class="fill" style="width:${(state.step+(state.solved?1:0))/7*100}%"></div></div><span class="progress-text">${state.step+1} / 7</span></div><section class="lesson-card"><div class="lesson-heading"><div><span class="eyebrow">FIND YOUR C · ${final?'THE BIG FINISH':`STRING ${state.step+1} OF 6`}</span><h1>${final?'Six strings. Find every C.':`Find C on the ${s.name} string.`}</h1></div><span class="step-chip" aria-hidden="true">${final?'✦':'C'}</span></div><p class="instruction">${final?'Your turn: find one C on each string. All six strings are now playable.':'Tap the fret where C lives. Only the purple string is playable.'}</p>${final?`<div class="final-count" aria-label="${state.found.length} of 6 C notes found">${strings.map((_,r)=>`<span class="${state.found.includes(r)?'done':''}"></span>`).join('')}</div>`:`<div class="string-steps" aria-label="String progression">${order.map((r,i)=>`<span class="string-step ${i===state.step?'current':i<state.step?'done':''}">${i<state.step?'✓ ':''}${strings[r].name}</span>`).join('')}<span class="string-step">All six ✦</span></div>`}<div class="board-hint"><span>Thin strings ↑ &nbsp; Thick strings ↓</span><span>Standard tuning · frets 1–12</span></div>${board()}<div class="legend"><span><i></i>Playable string${final?'s':''}</span>${!final&&state.hint>=1?'<span><i class="gold"></i>Hint notes</span>':''}<span><i class="green"></i>C found</span></div><div id="feedback" role="status" aria-live="polite" aria-atomic="true">${feedback()}</div><div class="lesson-actions">${state.solved?`<span class="action-note">${final?'You made it around the neck.':'One more little connection.'}</span><button class="primary" data-action="next">${final?'Finish lesson':state.step===5?'Try all six':'Next string'} <span aria-hidden="true">→</span></button>`:final?`<button class="text-button" data-action="review">Review the strings again</button><span class="action-note">${state.found.length} / 6 found</span>`:state.hint===0?'<span class="action-note">No rush. Give it a try.</span><button class="secondary" data-action="hint">Need a hint?</button>':state.hint<3?`<span class="action-note">Hint ${state.hint} of 3 · No lives to lose.</span><button class="secondary" data-action="hint">${state.hint===1?'Another hint':'Show me C'}</button>`:'<span class="action-note">Tap the revealed C to keep going.</span>'}</div></section><p class="footnote">No timer. No lives. Learning takes a little exploring.</p></main>`;}
function complete(){return `<main class="complete-shell"><div class="celebration">${mascot()}</div><span class="eyebrow">FIRST LESSON · COMPLETE</span><h1>You’ve got a C<br>on every string.</h1><p>Six little landmarks. One more way to feel at home on the fretboard.</p><section class="recap"><h2>Your C-note map</h2><div class="recap-notes">${order.map(r=>`<div class="recap-note"><span>${strings[r].name}</span><strong>${target(r)}</strong><small>FRET</small></div>`).join('')}</div></section><div class="completion-actions"><button class="primary" data-action="start">Play it again ↻</button><button class="secondary" data-action="home">Back to trail</button></div><p class="footnote">You completed a practice round${state.hintsUsed?' with hints along the way':''}. Try again later to see what sticks.<br>Progress resets when you refresh. No personal data is collected by this prototype.</p></main>`;}
function render(focus=false){app.innerHTML=state.view==='path'?path():state.view==='complete'?complete():lesson();if(focus){const h=app.querySelector('h1');h.tabIndex=-1;h.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}}
function start(){state={view:'lesson',step:0,hint:0,solved:false,found:[],wrong:null,mistakes:0,hintsUsed:0};render(true);}
function hint(){if(state.step===6||state.solved||state.hint>=3)return;state.hint++;state.hintsUsed++;state.wrong=null;render();}
app.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const action=b.dataset.action;if(action){switch(action){case 'start':start();break;case 'home':reset();break;case 'exit':leaveDialog.showModal();break;case 'hint':hint();break;case 'review':start();break;case 'next':if(!state.solved)return;if(state.step===6){state.view='complete';render(true);}else{state.step++;state.hint=0;state.solved=false;state.wrong=null;render(true);}break;}return;}if(b.dataset.row===undefined||state.view!=='lesson'||state.solved)return;const row=Number(b.dataset.row),f=Number(b.dataset.fret);if(!activeRow(row)||state.found.includes(row))return;if(f===target(row)){state.wrong=null;if(state.step===6){state.found.push(row);state.solved=state.found.length===6;}else state.solved=true;render();const next=app.querySelector('[data-action="next"]');if(next)next.focus({preventScroll:true});}else{state.mistakes++;state.wrong=`${row}:${f}`;if(state.step<6&&state.hint===0){state.hint=1;state.hintsUsed++;}render();const retry=app.querySelector(`[data-row="${row}"][data-fret="${f}"]`);retry?.focus({preventScroll:true});}});
document.querySelector('.brand').addEventListener('click',e=>{e.preventDefault();if(state.view==='lesson')leaveDialog.showModal();else reset();});
document.querySelector('#stay').onclick=()=>leaveDialog.close();
document.querySelector('#leave').onclick=()=>{leaveDialog.close();reset();};
reset();
